  "Happy birthday to someone who inspires me every day. Keep shining!": "தினமும் என்னை ஊக்குவிக்கும் உனக்கு பிறந்தநாள் வாழ்த்துகள். எப்போதும் ஜொலித்திடு!",
  "Have 5 crackers burning at once": "ஒரே நேரத்தில் 5 பட்டாசுகள் எரியட்டும்",
