  "Hello": "வணக்கம்",
  "Here’s to big dreams, small joys and everything in between. Have your best year yet!": "பெரிய கனவுகள், சின்ன சந்தோஷங்கள், இடையில் உள்ள எல்லாவற்றுக்கும். இதுவே உன் சிறந்த வருடமாகட்டும்!",
  "Here’s to every year we have shared, and all the ones still to come.": "நாம் பகிர்ந்த ஒவ்வொரு வருடத்துக்கும், இனி வரப்போகும் எல்லா வருடங்களுக்கும்.",
