  "Top Daily Diya scores: stars first, then speed.": "தினசரி தீபத்தின் சிறந்த மதிப்பெண்கள்: முதலில் நட்சத்திரங்கள், பிறகு வேகம்.",
  "Top Daily Rocket scores.": "தினசரி ராக்கெட்டின் சிறந்த மதிப்பெண்கள்.",
  "This leaderboard opens soon.": "இந்த லீடர்போர்டு விரைவில் திறக்கும்.",
