  "Top Gratitude": "சிறந்த நன்றியுணர்வு",
  "The most people lit up with gratitude: today, this week and of all time.": "நன்றியுடன் அதிகமானவர்களை ஒளிரச் செய்தவர்கள்: இன்று, இந்த வாரம், எல்லா காலமும்.",
