  "Thanjavur": "தஞ்சாவூர்",
  "Thank You": "நன்றி",
  "Thank you for the lovely wishes! Sending a sky full of light right back to you.": "அன்பான வாழ்த்துகளுக்கு நன்றி! ஒரு வானம் நிறைய ஒளியை உங்களுக்குத் திருப்பி அனுப்புகிறேன்.",
  "Thank you,": "நன்றி,",
  "That code isn’t valid": "அந்தக் குறியீடு சரியில்லை",
  "The app reads the names, birthdays and photos of contacts that have a birthday, so it can remind you. They stay on this phone and are never uploaded.": "பிறந்தநாள் உள்ள தொடர்புகளின் பெயர், பிறந்தநாள், படங்களை ஆப் படிக்கிறது, நினைவூட்டுவதற்காக. அவை இந்தப் போனிலேயே இருக்கும், ஒருபோதும் பதிவேற்றப்படாது.",
  "The bigger crackers cost gems. Everyday crackers and sparkler writing are always free.": "பெரிய பட்டாசுகளுக்கு ஜெம்ஸ் தேவை. தினசரி பட்டாசுகளும் மத்தாப்பு எழுத்தும் எப்போதும் இலவசம்.",
  "The camera is busy. Using the camera view instead.": "கேமரா பிஸியாக உள்ளது. கேமரா காட்சி பயன்படுத்தப்படுகிறது.",
  "The headline flies across the sky; the message appears on the card.": "தலைப்பு வானத்தில் பறக்கும்; செய்தி அட்டையில் தெரியும்.",
  "The link contains the whole card, so nothing is uploaded. Anyone who opens it sees the show.": "லிங்கிலேயே முழு அட்டையும் உள்ளது, எதுவும் பதிவேற்றப்படாது. திறக்கும் எவரும் நிகழ்ச்சியைப் பார்க்கலாம்.",
  "The link contains the whole card, so nothing is uploaded. Host the game online (for example GitHub Pages or Netlify) so friends can open the link.": "லிங்கிலேயே முழு அட்டையும் உள்ளது, எதுவும் பதிவேற்றப்படாது. நண்பர்கள் லிங்கைத் திறக்க கேமை ஆன்லைனில் வையுங்கள் (எ.கா. GitHub Pages அல்லது Netlify).",
  "The sky is full of light. Burst it first!": "வானம் ஒளியால் நிறைந்துள்ளது. முதலில் வெடியுங்கள்!",
