  "Wishing you sweets, sparkle and the warmth of family this Diwali.": "இந்தத் தீபாவளியில் இனிப்பு, ஜொலிப்பு, குடும்பத்தின் அரவணைப்பு கிடைக்க வாழ்த்துகள்.",
  "With you, every ordinary day feels like a celebration.": "உன்னுடன் ஒவ்வொரு சாதாரண நாளும் கொண்டாட்டம் போல.",
