  "You light up my sky every single day.": "ஒவ்வொரு நாளும் நீ என் வானத்தை ஒளிரச் செய்கிறாய்.",
  "You made my day. Thank you from the bottom of my heart.": "என் நாளை இனிமையாக்கினாய். மனமார்ந்த நன்றி.",
