  "A rocket flies only if its arrow’s lane is empty. A blocked tap burns a fuse.": "அம்புக்குறியின் பாதை காலியாக இருந்தால் மட்டுமே ராக்கெட் பறக்கும். தடைபட்ட தட்டல் ஒரு திரியை எரிக்கும்.",
  "Launch a rocket within 1.5 s of freeing it for a Chain and a bigger firework.": "ராக்கெட் விடுபட்ட 1.5 s-க்குள் ஏவுங்கள்: சங்கிலியும் பெரிய வாணமும் கிடைக்கும்.",
  "Wave {0}/{1}": "அலை {0}/{1}",
  "Wave {0}": "அலை {0}",
  "Wave {0} cleared!": "அலை {0} முடிந்தது!",
  "Choose a cracker. Touch its fuse with the sparkler.": "ஒரு பட்டாசைத் தேர்ந்தெடுங்கள். கம்பி மத்தாப்பால் அதன் திரியைத் தொடுங்கள்.",
  "Choose crackers. Sweep the sparkler across their fuses.": "பட்டாசுகளைத் தேர்ந்தெடுங்கள். கம்பி மத்தாப்பை அவற்றின் திரிகள் மேல் தேய்த்துச் செல்லுங்கள்.",
  "Drag to a fuse": "திரி வரை இழுங்கள்",
  "Sparkler: drag it onto a cracker's fuse": "கம்பி மத்தாப்பு: பட்டாசின் திரி வரை இழுங்கள்",
