  "Play today’s Daily Sky": "இன்றைய டெய்லி ஸ்கை விளையாடுங்கள்",
  "The leaderboard is in the Android app, with Google Play Games.": "லீடர்போர்டு Android ஆப்பில், Google Play Games உடன் உள்ளது.",
  "Your best Daily Sky score: {0}": "டெய்லி ஸ்கையில் உங்கள் சிறந்த மதிப்பெண்: {0}",
  "Loading the leaderboard…": "லீடர்போர்டு ஏற்றப்படுகிறது…",
  "Couldn’t load the leaderboard. Check your connection and try again.": "லீடர்போர்டை ஏற்ற முடியவில்லை. இணைப்பைச் சரிபார்த்து மீண்டும் முயலுங்கள்.",
  "Sign in to Google Play Games to see who is winning.": "யார் முன்னணி என்று பார்க்க Google Play Games-ல் உள்நுழையுங்கள்.",
  "No scores yet this week. Play today’s Daily Sky to be the first.": "இந்த வாரம் இன்னும் மதிப்பெண் இல்லை. இன்றைய டெய்லி ஸ்கை விளையாடி முதலிடம் பிடியுங்கள்.",
  "No scores yet. Play today’s Daily Sky to be the first.": "இன்னும் மதிப்பெண் இல்லை. இன்றைய டெய்லி ஸ்கை விளையாடி முதலிடம் பிடியுங்கள்.",
  "Unlimited hints with Premium": "பிரீமியத்தில் அளவற்ற குறிப்புகள்",
  "Never get stuck in Diya Path or Rocket Rush. Plus no ads and every cracker free.": "தீபப் பாதை, ராக்கெட் ரஷ் இரண்டிலும் ஒருபோதும் சிக்க மாட்டீர்கள். கூடவே விளம்பரம் இல்லை, ஒவ்வொரு பட்டாசும் இலவசம்.",
  "Every chapter of Diya Path and Rocket Rush, open now. Plus no ads and every cracker free.": "தீபப் பாதை, ராக்கெட் ரஷ் இரண்டின் ஒவ்வொரு அத்தியாயமும் இப்போதே திறந்திருக்கும். கூடவே விளம்பரம் இல்லை, ஒவ்வொரு பட்டாசும் இலவசம்.",
  "Play every past daily puzzle": "பழைய தினசரி புதிர்கள் அனைத்தையும் விளையாடு",
  "Missed a day? Premium opens every past Daily Diya and Daily Rocket. Plus no ads and every cracker free.": "ஒரு நாள் தவறிவிட்டதா? பிரீமியம் பழைய தினசரி தீபம், தினசரி ராக்கெட் அனைத்தையும் திறக்கும். கூடவே விளம்பரம் இல்லை, ஒவ்வொரு பட்டாசும் இலவசம்.",
  "Every cracker free with Premium": "பிரீமியத்தில் ஒவ்வொரு பட்டாசும் இலவசம்",
  "Finales, cakes and rocket combos with no gems, plus no ads and unlimited puzzle hints.": "ஃபினாலே, கேக், ராக்கெட் காம்போ ஜெம்ஸ் இல்லாமலே, கூடவே விளம்பரம் இல்லை, அளவற்ற புதிர் குறிப்புகள்.",
  "No banners or videos, every cracker free, and unlimited puzzle hints.": "பேனரும் இல்லை, வீடியோவும் இல்லை, ஒவ்வொரு பட்டாசும் இலவசம், அளவற்ற புதிர் குறிப்புகள்.",
  "No ads. Every cracker. Every level.": "விளம்பரம் இல்லை. ஒவ்வொரு பட்டாசும். ஒவ்வொரு நிலையும்.",
  "One payment of {0}, charged to your {1} when you confirm. Not a subscription: nothing renews, and Premium is yours to keep. Restore it on a new phone with the same account.": "{0} ஒருமுறை கட்டணம், நீங்கள் உறுதிசெய்ததும் உங்கள் {1} இலிருந்து பெறப்படும். இது சந்தா அல்ல: எதுவும் புதுப்பிக்கப்படாது, பிரீமியம் என்றும் உங்களுடையது. அதே கணக்குடன் புதிய போனில் மீட்டெடுக்கலாம்.",
  "{0} once": "{0} ஒருமுறை",
  "Pay once, keep forever": "ஒருமுறை செலுத்து, என்றும் வைத்திரு",
  "Get Premium forever · {0}": "என்றென்றும் பிரீமியம் பெறு · {0}",
  "One payment, no subscription": "ஒருமுறை கட்டணம், சந்தா இல்லை",
  "Every future update included": "இனி வரும் எல்லா அப்டேட்களும் சேர்த்து",
  "Active · no ads, every cracker free": "செயலில் · விளம்பரம் இல்லை, ஒவ்வொரு பட்டாசும் இலவசம்",
  "No ads, free crackers, every puzzle level": "விளம்பரம் இல்லை, இலவச பட்டாசுகள், ஒவ்வொரு புதிர் நிலையும்",
  "Welcome to Premium ✨ No ads, every cracker free, every level open": "பிரீமியத்துக்கு வரவேற்கிறோம் ✨ விளம்பரம் இல்லை, ஒவ்வொரு பட்டாசும் இலவசம், ஒவ்வொரு நிலையும் திறந்தது",
  "Every cracker. Every level.": "ஒவ்வொரு பட்டாசும். ஒவ்வொரு நிலையும்.",
