  "Collect today’s gift and play the Daily Sky before midnight to keep your streak": "இன்றைய பரிசைப் பெற்று, நள்ளிரவுக்கு முன் தினசரி வானம் விளையாடுங்கள், தொடர் நாட்கள் தொடரும்",
  "You just lit {0}": "நீங்கள் இப்போது {0} கொளுத்தினீர்கள்",
  "Keep it, and every other cracker, free with Premium. No ads, and 1,000 levels each in Diya Path and Rocket Rush.": "இதையும், மற்ற எல்லா பட்டாசுகளையும், பிரீமியம் மூலம் இலவசமாகப் பெறுங்கள். விளம்பரங்கள் இல்லை, தீபப் பாதை மற்றும் ராக்கெட் ரஷ் ஒவ்வொன்றிலும் 1,000 நிலைகள்.",
  "No ads, every cracker free and 1,000 levels each in Diya Path and Rocket Rush, all through the festival.": "விளம்பரங்கள் இல்லை, எல்லா பட்டாசுகளும் இலவசம், தீபப் பாதை மற்றும் ராக்கெட் ரஷ் ஒவ்வொன்றிலும் 1,000 நிலைகள், பண்டிகை முழுவதும்.",
  "Unlock 1,000 levels each in Diya Path and Rocket Rush": "தீபப் பாதை மற்றும் ராக்கெட் ரஷ் ஒவ்வொன்றிலும் 1,000 நிலைகளைத் திற",
  "No ads · every cracker free with Premium": "விளம்பரங்கள் இல்லை · பிரீமியம் மூலம் எல்லா பட்டாசுகளும் இலவசம்",
  "Grand finales, 3D skylines, AR, and 1,000 levels each in Diya Path and Rocket Rush with unlimited hints.": "கிராண்ட் ஃபினாலே, 3D வானக்கோடுகள், AR, மற்றும் தீபப் பாதை மற்றும் ராக்கெட் ரஷ் ஒவ்வொன்றிலும் 1,000 நிலைகள், வரம்பற்ற குறிப்புகளுடன்.",
  "Premium makes every cracker free and opens 1,000 levels each in Diya Path and Rocket Rush with unlimited hints.": "பிரீமியம் எல்லா பட்டாசுகளையும் இலவசமாக்கி, தீபப் பாதை மற்றும் ராக்கெட் ரஷ் ஒவ்வொன்றிலும் 1,000 நிலைகளைத் திறக்கிறது, வரம்பற்ற குறிப்புகளுடன்.",
