  "All 15 landmarks in 3D, AR fireworks, and the sacred Diya Path backgrounds.": "அனைத்து 15 சின்னங்களும் 3D-யில், AR வாணவேடிக்கை, தீபப் பாதையின் புனித பின்னணிகள்.",
  "All 15 landmarks in 3D, and the sacred Diya Path backgrounds.": "அனைத்து 15 சின்னங்களும் 3D-யில், தீபப் பாதையின் புனித பின்னணிகள்.",
  "A safer streak": "இன்னும் பாதுகாப்பான தொடர்",
  "Miss a day twice a week and keep your streak and its bigger gifts.": "வாரத்துக்கு இருமுறை ஒரு நாள் தவறினாலும் உங்கள் தொடரும் அதன் பெரிய பரிசுகளும் தொடரும்.",
  "You’ve lit {0} kinds of crackers so far. With Premium, all {1} are free.": "இதுவரை {0} வகை பட்டாசுகளைக் கொளுத்தியுள்ளீர்கள். பிரீமியத்தில் அனைத்து {1}-ம் இலவசம்.",
  "It’s Diwali week. Light the whole street.": "இது தீபாவளி வாரம். தெரு முழுவதையும் ஒளிரச் செய்யுங்கள்.",
  "Diwali is tomorrow. Light the whole street.": "நாளை தீபாவளி. தெரு முழுவதையும் ஒளிரச் செய்யுங்கள்.",
  "Diwali is in {0} days. Light the whole street.": "தீபாவளிக்கு இன்னும் {0} நாட்கள். தெரு முழுவதையும் ஒளிரச் செய்யுங்கள்.",
  "Changed your mind? You can ask Google Play for a refund within 48 hours of buying.": "மனம் மாறிவிட்டதா? வாங்கிய 48 மணி நேரத்துக்குள் Google Play-யில் பணத்தைத் திரும்பக் கேட்கலாம்.",
  "Any time": "எப்போது வேண்டுமானாலும்",
  "A thousand crackers on a bamboo pole": "மூங்கில் கம்பத்தில் ஆயிரம் பட்டாசுகள்",
  "Every cracker free": "ஒவ்வொரு பட்டாசும் இலவசம்",
  "Finales, saravedi and seven shots, every night": "ஃபினாலே, நீள சரவெடி, செவன் ஷாட், ஒவ்வொரு இரவும்",
  "Five Premium crackers": "ஐந்து பிரீமியம் பட்டாசுகள்",
  "The thousand-cracker Hazaar ladi, saravedi, seven shot, double shot and Lakshmi vedi. One free try each.": "ஆயிரம் பட்டாசுகளின் ஆயிரம் சரவெடி, நீள சரவெடி, செவன் ஷாட், டபுள் ஷாட், லட்சுமி வெடி. ஒவ்வொன்றுக்கும் ஒரு இலவச முயற்சி.",
  "Grand finales, wedding cakes, sutli bombs and more. One of each costs {0} without Premium.": "கிராண்ட் ஃபினாலே, வெட்டிங் கேக், சுத்லி வெடி இன்னும் பல. பிரீமியம் இல்லாமல் ஒவ்வொன்றையும் ஒருமுறை கொளுத்த {0} ஆகும்.",
  "A grand finale and a wedding cake every evening for a month: {0} (about {1} at gem-pack prices). With Premium they’re free, with everything above.": "ஒரு மாதம் தினமும் மாலை ஒரு கிராண்ட் ஃபினாலே, ஒரு வெட்டிங் கேக்: {0} (ஜெம் பேக் விலையில் சுமார் {1}). பிரீமியத்தில் இவை இலவசம், மேலே உள்ள அனைத்துடனும்.",
  "A grand finale and a wedding cake every evening for a month: {0}. With Premium they’re free, with everything above.": "ஒரு மாதம் தினமும் மாலை ஒரு கிராண்ட் ஃபினாலே, ஒரு வெட்டிங் கேக்: {0}. பிரீமியத்தில் இவை இலவசம், மேலே உள்ள அனைத்துடனும்.",
  "Light the {0} with Premium": "பிரீமியத்தில் {0} கொளுத்துங்கள்",
  "Hazaar ladi, saravedi, seven shot, double shot and Lakshmi vedi, lit with your sparkler. Plus no ads and every cracker free.": "ஆயிரம் சரவெடி, நீள சரவெடி, செவன் ஷாட், டபுள் ஷாட், லட்சுமி வெடி, உங்கள் கம்பி மத்தாப்பால் பற்ற வையுங்கள். கூடவே விளம்பரம் இல்லை, ஒவ்வொரு பட்டாசும் இலவசம்.",
  "Hazaar ladi, saravedi, seven shot and more": "ஆயிரம் சரவெடி, நீள சரவெடி, செவன் ஷாட் இன்னும் பல",
  "1 free try each": "ஒவ்வொன்றுக்கும் 1 இலவச முயற்சி",
  "Big crackers: finale, cake, sutli bomb…": "பெரிய பட்டாசுகள்: ஃபினாலே, கேக், சுத்லி வெடி…",
  "Three Premium sky shells": "மூன்று பிரீமியம் வான் ஷெல்கள்",
  "Peacock, butterfly and magic wand bursts. One free try each.": "மயில், பட்டாம்பூச்சி, மந்திரக்கோல் வெடிப்புகள். ஒவ்வொன்றுக்கும் ஒரு இலவச முயற்சி.",
  "Peacock, butterfly and magic wand shells, lit with your sparkler. Plus no ads and every cracker free.": "மயில், பட்டாம்பூச்சி, மந்திரக்கோல் ஷெல்கள், உங்கள் கம்பி மத்தாப்பால் பற்ற வையுங்கள். கூடவே விளம்பரம் இல்லை, ஒவ்வொரு பட்டாசும் இலவசம்.",
  "Peacock, butterfly and magic wand shells": "மயில், பட்டாம்பூச்சி, மந்திரக்கோல் ஷெல்கள்",
