  "Sneak in, find the hidden crackers, light them up, and don't get caught by Seth-ji.": "பதுங்கி நுழை, ஒளிந்திருக்கும் பட்டாசுகளைக் கண்டுபிடி, கொளுத்து — சேட்ஜியிடம் மாட்டிக்கொள்ளாதே.",
  "All streets": "எல்லாத் தெருக்களும்",
  "Step {0} of {1}": "படி {0} / {1}",
  "Let's go!": "போகலாம்!",
  "Find the crackers": "பட்டாசுகளைக் கண்டுபிடி",
  "Glowing gifts and gems are hidden by the stalls. Tap one in reach to put it in your bag.": "ஒளிரும் பரிசுகளும் ரத்தினங்களும் கடைகளின் அருகே ஒளிந்துள்ளன. அருகிலுள்ள ஒன்றைத் தட்டி உன் பையில் போடு.",
  "Set it down or throw it": "கீழே வை அல்லது வீசு",
  "Tap a cracker in your bag to put it on the street. Drag it up to throw it anywhere: a stall, a tree, the cart.": "பையிலுள்ள பட்டாசைத் தட்டித் தெருவில் வை. மேலே இழுத்து எங்கும் வீசு: கடை, மரம், வண்டி.",
  "Light it up": "கொளுத்து",
  "Load the donkey": "கழுதையின் மேல் ஏற்று",
  "Drag a cracker onto the animal's basket and press Fire: it walks off with it going off on its back.": "பட்டாசை விலங்கின் கூடைக்கு இழுத்து வெடி அழுத்து: அது முதுகில் வெடிக்க வெடிக்க நடந்து போகும்.",
  "Don't get caught": "மாட்டிக்கொள்ளாதே",
  "Seth-ji, the old man and the dog are watching. Slip behind the cart or the crates when the eye fills up.": "சேட்ஜி, தாத்தா, நாய் பார்த்துக்கொண்டிருக்கிறார்கள். கண் நிறையும்போது வண்டி அல்லது பெட்டிகளுக்குப் பின்னால் ஒளிந்துகொள்.",
